class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        int maxWidth = 0;
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0});
        Queue<TreeNode> nodeQueue = new LinkedList<>();
        nodeQueue.offer(root);
        while (!nodeQueue.isEmpty()) {
            int size = nodeQueue.size();
            int first = 0, last = 0;
            int offset = -1;
            for (int i = 0; i < size; i++) {
                TreeNode node = nodeQueue.poll();
                int idx = queue.poll()[0];
                if (offset == -1) offset = idx;
                idx -= offset;
                if (i == 0) first = idx;
                if (i == size - 1) last = idx;
                if (node.left != null) {
                    nodeQueue.offer(node.left);
                    queue.offer(new int[]{2 * idx});
                }
                if (node.right != null) {
                    nodeQueue.offer(node.right);
                    queue.offer(new int[]{2 * idx + 1});
                }
            }
            maxWidth = Math.max(maxWidth, last - first + 1);
        }
        return maxWidth;
    }
}

class Solution {
    private int maxWidth = 0;
    private java.util.List<Integer> firstIndices = new java.util.ArrayList<>();

    public int widthOfBinaryTree(TreeNode root) {
        maxWidth = 0;
        firstIndices = new java.util.ArrayList<>();
        dfs(root, 0, 0);
        return maxWidth;
    }

    private void dfs(TreeNode node, int depth, int index) {
        if (node == null) return;
        if (depth == firstIndices.size()) {
            firstIndices.add(index);
        }
        int width = index - firstIndices.get(depth) + 1;
        maxWidth = Math.max(maxWidth, width);
        dfs(node.left, depth + 1, 2 * (index - firstIndices.get(depth)));
        dfs(node.right, depth + 1, 2 * (index - firstIndices.get(depth)) + 1);
    }
}
